from textual.widget import Widget
from textual.geometry import Size
from textual._resolve import resolve_box_models
from textual.css.scalar import Scalar

class SizedWidget(Widget):
    def get_content_width(self, container, viewport):
        return 7
    def get_content_height(self, container, viewport, width):
        return 3

def mk(width=None,height=None,cls=Widget):
    w=cls()
    if width is not None: w.styles.width=width
    if height is not None: w.styles.height=height
    return w

for greedy in (True, False):
    ws=[mk('1fr',5,SizedWidget),mk('1fr',5,SizedWidget)]
    res=resolve_box_models([Scalar.parse('1fr')]*2, ws, Size(30,20), Size(80,24), Size(0,0), 'width', greedy)
    print('greedy',greedy, [(m.width,m.height) for m in res])
